# Valid key types
d = {
    42:          "int key",
    3.14:        "float key",     # valid but risky
    "name":      "str key",
    True:        "bool key",
    (1, 2):      "tuple key",
    frozenset({1,2}): "frozenset key",
    None:        "None key",
}
print(d[42], d["name"], d[(1,2)])  # int key / str key / tuple key

# Invalid key: list raises TypeError
try:
    bad = {[1,2]: "value"}
except TypeError as e:
    print(e)   # unhashable type: 'list'

# True == 1 and hash(True) == hash(1): same key!
d2 = {True: "first", 1: "second"}
print(d2)        # {True: 'second'}  -- only one entry; value overwritten
print(len(d2))   # 1

d3 = {False: "zero", 0: "also zero"}
print(d3)        # {False: 'also zero'}
print(len(d3))   # 1

# Ordered by insertion (Python 3.7+)
d4 = {"c": 3, "a": 1, "b": 2}
print(list(d4.keys()))   # ['c', 'a', 'b']  -- insertion order preserved

d = {"name": "Alice", "age": 25}

# d[k] vs d.get()
print(d["name"])              # Alice
try:
    print(d["score"])         # KeyError!
except KeyError as e:
    print(f"KeyError: {e}")

print(d.get("score"))         # None  (no error)
print(d.get("score", 0))      # 0     (custom default)
print(d.get("name",  "?"))    # Alice (key exists, default ignored)

# setdefault: insert-then-return
d.setdefault("score", 100)    # inserts "score": 100
print(d["score"])             # 100
d.setdefault("score", 200)    # key already exists: no change
print(d["score"])             # 100  (still 100!)

# Grouping with setdefault
words = ["apple","ant","banana","blueberry","avocado","cherry"]
grouped = {}
for word in words:
    grouped.setdefault(word[0], []).append(word)
print(grouped)
# {'a': ['apple','ant','avocado'], 'b': ['banana','blueberry'], 'c': ['cherry']}

# pop
removed = d.pop("age")        # removes and returns
print(removed)                # 25
print("age" in d)             # False

d.pop("nonexistent", "safe")  # no KeyError with default
# d.pop("nonexistent")        # would raise KeyError!

# popitem: removes last inserted item (Python 3.7+ guaranteed LIFO)
d2 = {"x": 1, "y": 2, "z": 3}
print(d2.popitem())           # ('z', 3)
print(d2)                     # {'x': 1, 'y': 2}

# update: merge in-place
base = {"a": 1, "b": 2}
base.update({"b": 99, "c": 3})   # b overwritten, c added
print(base)   # {'a': 1, 'b': 99, 'c': 3}

base.update(d=4, e=5)            # keyword form
print(base)   # {'a': 1, 'b': 99, 'c': 3, 'd': 4, 'e': 5}

# |= in-place merge (Python 3.9+)
d3 = {"x": 1}
d3 |= {"y": 2, "z": 3}
print(d3)   # {'x': 1, 'y': 2, 'z': 3}

