A = {1, 2, 3, 4, 5}
B = {4, 5, 6, 7, 8}

# Union: all elements from both
print(A | B)                  # {1, 2, 3, 4, 5, 6, 7, 8}
print(A.union(B))             # same
print(A.union([4,5,6,7,8]))   # method accepts any iterable!
% print(A | [4,5,6])          # TypeError: operator needs set

# Intersection: only common elements
print(A & B)                  # {4, 5}
print(A.intersection(B))      # {4, 5}

# Difference: in A but not B
print(A - B)                  # {1, 2, 3}
print(B - A)                  # {6, 7, 8}  (not symmetric!)

# Symmetric difference: in exactly one of A, B
print(A ^ B)                  # {1, 2, 3, 6, 7, 8}
print(A.symmetric_difference(B))  # same

# Multiple sets with methods
C = {5, 6, 9}
print(A.union(B, C))          # {1,2,3,4,5,6,7,8,9}
print(A.intersection(B, C))   # {5}   common to all three

