# 2. Performance Profiling: Linear Array Sweep vs. Constant Hash Lookup
import time
large_list = list(range(1_000_000))
large_set  = set(range(1_000_000))

t0 = time.perf_counter()
_ = 999_999 in large_list
print(f"list: {time.perf_counter()-t0:.4f}s")   # ~0.01s (O(n) dependency loop)

t0 = time.perf_counter()
_ = 999_999 in large_set
print(f"set : {time.perf_counter()-t0:.6f}s")   # ~0.0000001s (O(1) constant index look)

