# 6. Graph Structures: Tracking Network Reachability via Constant Sets
graph = {1:[2,3], 2:[4], 3:[4,5], 4:[], 5:[]}
def reachable(start, graph):
    visited = {start}
    queue   = [start]
    while queue:
        node = queue.pop(0)
        for nb in graph[node]:
            if nb not in visited:     # Fast constant evaluation barrier
                visited.add(nb)
                queue.append(nb)
    return visited
print(reachable(1, graph))   # {1, 2, 3, 4, 5}

# 7. Combinatorial Generation: Designing Power Sets via Immutable Composition
def power_set(s):
    ps = {frozenset()}
    for elem in s:
        ps = ps | {sub | {elem} for sub in ps}
    return ps
print(power_set({1,2,3}))
